const EINFO={1:{u:"工业上主要用来合成氨造化肥，以及在炼油中给油品加氢；也是燃料电池和火箭的燃料。",a:["合成氨化肥","氢燃料电池车","石油精炼加氢","氢化植物油"]},2:{u:"沸点最低，是超导磁体唯一可行的冷却剂；化学上完全惰性，还用作保护气和深潜呼吸气。",a:["医院 MRI 磁体冷却","气球与飞艇","深海潜水混合气","半导体制造保护气"]},3:{u:"最轻的金属，储能能力极高，几乎所有可充电设备都靠它；碳酸锂还是双相情感障碍的经典药物。",a:["手机与电动车锂电池","双相障碍治疗药","耐热玻璃陶瓷炊具","高温润滑脂"]},4:{u:"又轻又硬且不产生火花，用于精密仪器与安全工具；对 X 射线几乎透明，是 X 光管的窗口材料。",a:["防爆无火花扳手","X 光机窗口","航天与卫星结构件","高端扬声器振膜"]},5:{u:"硼硅玻璃耐骤冷骤热，是实验室和烤箱玻璃器皿的基础；硼还能强烈吸收中子，用于反应堆控制。",a:["耐热玻璃锅具与量杯","洗涤剂中的硼砂","核反应堆控制棒","玻璃纤维与农用硼肥"]},6:{u:"所有有机物和生命的骨架元素。同一个元素能变成最软的石墨和最硬的金刚石，用途横跨整个工业。",a:["铅笔芯与电池电极（石墨）","切割工具与首饰（金刚石）","净水器与口罩活性炭","碳纤维车架与球拍"]},7:{u:"空气的主要成分。合成氨把它变成化肥，直接支撑了全球约一半人口的粮食供给。",a:["氮肥（哈伯法）","液氮冷冻与冷链","食品包装充氮保鲜","轮胎充氮"]},8:{u:"呼吸赖以为生，也是炼钢的关键 —— 现代炼钢靠吹氧脱碳。医疗与焊接同样离不开它。",a:["医用供氧与急救","炼钢吹氧","氧炔焊接与切割","污水处理曝气"]},9:{u:"牙膏里的氟化物能显著防蛀；聚四氟乙烯就是不粘锅涂层。制冷剂和大量药物也含氟。",a:["牙膏防蛀氟化物","不粘锅涂层（特氟龙）","空调冰箱制冷剂","含氟药物与铀浓缩"]},10:{u:"通电发出标志性的橙红色光，霓虹招牌因此得名；也用于高压指示灯和准分子激光。",a:["霓虹灯招牌","高压电指示灯","准分子激光器","低温制冷剂"]},11:{u:"以食盐形式进入每一餐，也是人体神经传导必需的电解质；工业上制烧碱、小苏打和路灯。",a:["食盐与人体电解质","小苏打与烧碱","高压钠灯路灯","钠冷快中子堆"]},12:{u:"密度最低的结构金属，笔记本外壳和汽车轻量化都靠镁铝合金；还是叶绿素的中心原子。",a:["笔记本与汽车镁合金件","烟花与照明弹","泻盐与抗酸胃药","叶绿素核心"]},13:{u:"轻、耐蚀、可无限回收，是用量仅次于铁的金属；从易拉罐到飞机机身都是它。",a:["易拉罐与铝箔","门窗与幕墙","飞机机身与轮毂","高压输电线"]},14:{u:"整个信息时代建立在硅晶圆上；同时以二氧化硅的形式构成玻璃、水泥和沙子。",a:["芯片与集成电路","太阳能电池板","玻璃与水泥","硅胶密封与干燥剂"]},15:{u:"生命的能量货币 ATP 和 DNA 骨架都含磷；农业上是三大肥料元素之一，缺它作物无法生长。",a:["磷肥","火柴头","DNA 与 ATP","阻燃剂与洗涤剂"]},16:{u:"硫酸产量常被用作衡量一国工业规模的指标；橡胶硫化让轮胎从黏软变得坚韧耐磨。",a:["硫酸（工业之母）","轮胎橡胶硫化","火药与烟花","农药杀菌与葡萄园"]},17:{u:"自来水消毒每年避免大量水源性疾病，是公共卫生史上最重要的措施之一；也是 PVC 塑料的原料。",a:["自来水与泳池消毒","84 消毒液与漂白剂","PVC 管材与地板","盐酸"]},18:{u:"空气中含量第三的气体，便宜又惰性，是焊接时隔绝氧气的首选保护气；也灌进中空玻璃隔热。",a:["氩弧焊保护气","中空玻璃填充","灯泡与荧光灯填充","金属冶炼保护气氛"]},19:{u:"与钠共同维持细胞内外的电位差，心跳和神经信号都依赖它；农业上是三大肥料元素之一。",a:["钾肥","香蕉等食物中的电解质","硝石（黑火药）","软肥皂与玻璃"]},20:{u:"骨骼和牙齿的主要成分；以石灰和水泥的形式，也是人类用量最大的建筑材料基础。",a:["骨骼与牙齿","水泥与石灰","钙片与牛奶","豆腐凝固剂、烟气脱硫"]},21:{u:"加进铝里能显著提高强度而几乎不增重，用于高端自行车架、棒球棒和航空部件。",a:["铝钪合金自行车架","棒球棒与航空件","金属卤化物灯","固体氧化物燃料电池"]},22:{u:"强度接近钢却轻得多，且与人体组织相容，是人工关节和牙种植体的标准材料。",a:["人工关节与牙种植体","飞机发动机与机体","钛白粉（涂料、防晒霜）","眼镜架与高端表壳"]},23:{u:"少量钒就能让钢的强度和韧性大幅提升，扳手、弹簧和工具钢都靠它；也用于大规模储能电池。",a:["铬钒钢工具与扳手","弹簧与轴承钢","钒液流储能电池","制硫酸催化剂"]},24:{u:"不锈钢之所以不锈，靠的就是铬在表面自发形成的致密氧化膜；电镀铬则提供镜面般的耐磨层。",a:["不锈钢餐具与厨具","水龙头与汽车镀铬件","皮革鞣制","颜料与耐火砖"]},25:{u:"炼钢时脱氧去硫，几乎所有钢材都含锰；高锰钢极耐冲击磨损，用于铁轨和挖掘机斗齿。",a:["钢铁脱氧与高锰钢铁轨","干电池正极","高锰酸钾消毒","铝合金与玻璃脱色"]},26:{u:"人类用量最大的金属，钢铁撑起了建筑、桥梁、汽车和铁路；在体内则是血红蛋白运氧的核心。",a:["钢筋、桥梁与汽车","血红蛋白运氧","永磁体与变压器铁芯","补铁剂与铁强化食品"]},27:{u:"锂电池正极的关键成分，也是维生素 B12 的中心原子；钴蓝自古就是最珍贵的蓝色颜料。",a:["锂电池正极材料","维生素 B12","钴蓝玻璃与陶瓷釉","超硬合金刀具、钴 60 放疗"]},28:{u:"不锈钢里的镍决定了它的韧性和耐蚀性；镍还广泛用于电镀、硬币和充电电池。",a:["不锈钢与耐蚀合金","镍氢/锂电池材料","硬币与电镀层","人造奶油氢化催化剂"]},29:{u:"导电性仅次于银而便宜得多，几乎所有电线和电路板都用铜；表面还能持续杀灭细菌。",a:["电线电缆与电路板","自来水管与暖气管","黄铜与青铜器件","医院抗菌门把手"]},30:{u:"镀锌是最经济有效的钢铁防锈手段，路灯杆和护栏都靠它；氧化锌还是物理防晒霜的主力成分。",a:["镀锌钢材防锈","物理防晒霜与痱子粉","黄铜","锌补充剂与干电池"]},31:{u:"氮化镓充电器之所以能做得又小又凉，就是因为镓基半导体损耗低；蓝光 LED 也是氮化镓做的。",a:["氮化镓快充充电器","蓝光与白光 LED","手机射频芯片","镓铟合金替代水银温度计"]},32:{u:"对红外线高度透明，是热成像和夜视镜头的标准材料；光纤中也靠掺锗调节折射率。",a:["热成像与夜视镜头","光纤芯掺杂","红外光学窗口","PET 塑料聚合催化剂"]},33:{u:"砷化镓芯片比硅更快更省电，手机射频前端普遍采用；三氧化二砷则是治疗白血病的有效药物。",a:["砷化镓射频芯片","高效太阳能电池","白血病治疗药物","曾用于木材防腐（现受限）"]},34:{u:"人体必需的微量元素，是抗氧化酶的活性中心；二硫化硒还是去屑洗发水的有效成分。",a:["抗氧化营养素","去屑洗发水","玻璃脱色与红色玻璃","复印机与激光打印感光鼓"]},35:{u:"溴系阻燃剂曾广泛用于电子外壳和家具泡沫；溴化银则是胶片摄影的感光核心。",a:["阻燃剂","胶片摄影感光材料","泳池消毒剂","镇静与抗癫痫药（历史）"]},36:{u:"比氩更重更惰性，灌进白炽灯能延长寿命、提高亮度；也用于高性能中空玻璃和摄影闪光灯。",a:["高效白炽灯与闪光灯","高性能中空玻璃","氪激光器","高速摄影光源"]},37:{u:"铷原子钟精度极高、成本远低于铯钟，广泛用于通信基站和卫星导航的时间同步。",a:["铷原子钟与基站授时","真空管吸气剂","光电倍增管","冷原子物理研究"]},38:{u:"烟花里那抹鲜艳的红色就是锶发出的；含锶牙膏则能封闭牙本质小管，缓解牙齿敏感。",a:["烟花与信号弹的红色","抗敏感牙膏","老式显像管玻璃","铁氧体永磁"]},39:{u:"白光 LED 的黄色荧光粉以钇为基础 —— 蓝光芯片加这层荧光粉才变成白光；也用于 YAG 激光。",a:["白光 LED 荧光粉","YAG 激光器","氧化锆陶瓷刀稳定剂","高温超导材料"]},40:{u:"几乎不吸收中子又耐高温高压，是核燃料棒包壳的唯一选择；氧化锆陶瓷则做成牙冠和陶瓷刀。",a:["核燃料棒包壳","氧化锆牙冠与陶瓷刀","止汗剂有效成分","耐火材料与铸造砂"]},41:{u:"铌钛超导线是 MRI 和粒子加速器磁体的标准材料；微量铌还能让管线钢更强更韧。",a:["MRI 与加速器超导磁体","高强度管线钢","电容器与首饰","喷气发动机超合金"]},42:{u:"含钼钢在高温下仍保持强度，用于刀具、钻头和高压管道；二硫化钼是耐极压的固体润滑剂。",a:["高速钢刀具与钻头","二硫化钼润滑剂","石油脱硫催化剂","植物必需微量元素"]},43:{u:"第一个人工合成的元素。锝 99m 是全世界使用最多的医用放射性同位素，每年数千万次显像检查靠它。",a:["核医学显像（骨扫描、心肌灌注）","甲状腺与肾功能检查","工业示踪"]},44:{u:"硬盘盘片中的钌薄层让磁记录密度大幅提升；也是电接触材料和多种工业催化剂的成分。",a:["硬盘磁记录层","电子接触与电阻","合成氨与制氢催化剂","耐磨钢笔尖"]},45:{u:"汽车三元催化器中最关键的一种金属，专门负责把氮氧化物还原成氮气，价格因此常年居高。",a:["汽车三元催化器","白金首饰的镀层","玻璃纤维成型模具","工业催化剂"]},46:{u:"能吸收自身体积数百倍的氢气，用于氢气提纯；也是汽车催化器和手机陶瓷电容的关键材料。",a:["汽车尾气催化器","手机中的陶瓷电容","氢气提纯与储存","牙科合金与首饰"]},47:{u:"导电导热性能均居所有金属之首，太阳能电池板正面的细密银浆栅线就是靠它导出电流；还有强抗菌性。",a:["太阳能电池银浆","首饰与餐具","抗菌敷料与伤口膏","电子触点与胶片摄影"]},48:{u:"镉黄、镉红是画家钟爱的鲜艳颜料；但镉毒性高且在体内蓄积，电池和电镀用途已大幅受限。",a:["镉黄/镉红颜料","镍镉电池（淘汰中）","量子点显示材料","核反应堆控制棒"]},49:{u:"氧化铟锡（ITO）既导电又透明，是所有触摸屏和液晶面板必需的透明电极，几乎无可替代。",a:["触摸屏与液晶透明电极","低熔点合金与保险丝","半导体与 LED","真空密封垫"]},50:{u:"熔点低又不易氧化，是电子焊锡的主角；镀在钢罐内壁就成了马口铁，用于食品罐头。",a:["电子焊锡","马口铁食品罐头","青铜器与乐器","PVC 塑料稳定剂"]},51:{u:"三氧化二锑是应用最广的阻燃增效剂，与溴系阻燃剂配合用于电视外壳和线缆；也用于铅酸电池板栅。",a:["阻燃剂增效成分","铅酸电池板栅","半导体与红外探测器","玻璃与陶瓷澄清剂"]},52:{u:"碲化镉薄膜太阳能电池成本低、弱光发电好，是大型光伏电站的重要技术路线；碲化铋则用于制冷片。",a:["碲化镉薄膜太阳能","半导体制冷片（车载冰箱）","易切削钢添加剂","可录光盘记录层"]},53:{u:"缺碘会导致甲状腺肿和儿童智力发育障碍，食盐加碘是覆盖人口最广的公共营养干预之一。",a:["碘盐防治甲状腺疾病","碘伏与碘酒消毒","X 光造影剂","碘钨灯"]},54:{u:"氙气大灯亮度接近日光且更省电；氙还是效率极高的太空离子推进剂，多个探测器靠它飞行。",a:["汽车氙气大灯","摄影闪光灯与影院灯","卫星与探测器离子推进","吸入式麻醉与医学成像"]},55:{u:"\"秒\"的国际定义就建立在铯 133 原子的跃迁频率上 —— 全球时间标准和 GPS 都以铯钟为基准。",a:["铯原子钟（秒的定义）","GPS 与电网授时","石油钻井高密度钻井液","光电与离子推进"]},56:{u:"硫酸钡不溶且不被吸收，喝下去能让消化道在 X 光下清晰显影，就是俗称的\"钡餐\"。",a:["钡餐消化道造影","石油钻井泥浆加重剂","烟花的绿色","玻璃与陶瓷釉"]},72:{u:"二氧化铪的高介电常数让晶体管在纳米尺度下不再漏电，是 45 纳米以下芯片能继续微缩的关键材料。",a:["芯片高 k 栅介质","核反应堆控制棒","等离子切割电极","喷气发动机超合金"]},73:{u:"钽电容体积小、容量大、性能稳定，是手机和笔记本主板上的常客；钽还与人体高度相容，用于骨科植入。",a:["手机与电脑钽电容","骨科与颅骨修复植入物","化工耐腐蚀反应器","硬质合金刀具"]},74:{u:"熔点是所有金属中最高的（3422 ℃）。碳化钨硬度仅次于金刚石，几乎所有金属切削刀具和钻头都用它。",a:["硬质合金刀具与钻头","白炽灯与卤素灯灯丝","飞镖与高尔夫配重","X 射线管靶材"]},75:{u:"地壳中最稀有的稳定元素之一。喷气发动机最热的涡轮叶片靠含铼超合金才能在接近熔点的环境下工作。",a:["喷气发动机涡轮叶片","汽油重整催化剂","高温热电偶","半导体与电子靶材"]},76:{u:"密度最大的天然元素。锇合金极耐磨，曾是高级钢笔尖和唱针的标准材料；四氧化锇是电镜染色剂。",a:["高级钢笔尖与唱针","电子显微镜染色剂","仪器轴承与触点","耐磨合金"]},77:{u:"铱火花塞电极极细且耐蚀，寿命可达普通火花塞数倍；地层中的铱异常还是恐龙灭绝小行星撞击的关键证据。",a:["长寿命铱火花塞","晶体生长坩埚","深空探测器热源包壳","恐龙灭绝的地质证据"]},78:{u:"汽车催化器中负责氧化一氧化碳和碳氢化合物；顺铂等铂类药物则是多种癌症化疗的一线方案。",a:["汽车尾气催化器","顺铂等抗癌药","首饰与实验室器皿","燃料电池催化剂"]},79:{u:"不氧化不变色且延展性极佳，电子接插件镀金是为了长期接触可靠；航天器也贴金膜隔绝红外辐射。",a:["首饰与金融储备","电子接插件镀金","牙科修复","航天器隔热金膜"]},80:{u:"唯一常温液态的金属。曾是温度计和血压计的标准，但因神经毒性正被全球逐步淘汰。",a:["温度计与血压计（淘汰中）","荧光灯与节能灯","牙科银汞合金","氯碱工业电解"]},81:{u:"毒性极强，曾作鼠药和\"继承粉\"而臭名昭著；如今主要用于心肌灌注显像和红外光学。",a:["心肌灌注显像","红外光学元件","高温超导材料","鼠药（已禁用）"]},82:{u:"密度大又便宜，是 X 光防护铅衣和铅板的标准材料；汽车启动电池至今仍以铅酸电池为主。",a:["汽车铅酸启动电池","X 光防护铅衣与铅玻璃","辐射屏蔽与配重","曾用于汽油与油漆（已禁）"]},83:{u:"毒性远低于同族的铅，正在多个场合取代铅：无铅焊料、无铅子弹、渔具配重；胃药\"次水杨酸铋\"也是它。",a:["止泻胃药（次水杨酸铋）","无铅焊料与子弹","化妆品珠光颜料","消防喷淋易熔合金"]},84:{u:"放射性极强，一克钋释放的热量足以让自身炽热。曾用于消除静电的电离器，也曾是航天器热源。",a:["静电消除器（工业与摄影）","航天器热源（历史）","中子源引发剂"]},85:{u:"地壳中最稀有的天然元素，全球任一时刻的总量不足一克。砹 211 正被研究用于靶向 α 放疗。",a:["靶向 α 放疗研究（癌症）"]},86:{u:"从土壤渗入室内的放射性气体，是仅次于吸烟的肺癌成因，许多国家要求新建住宅做氡检测。",a:["室内空气污染检测对象","地质与地震监测示踪","放射治疗（历史用途）"]},87:{u:"天然存在量极少，半衰期仅 22 分钟，从未被大量制得。没有实际用途，仅用于原子结构研究。",a:[]},88:{u:"居里夫妇发现的元素。曾大量用于夜光表盘，导致\"镭女郎\"职业中毒事件，如今已被安全材料全面取代。",a:["夜光表盘与早期放疗（均已淘汰）","工业射线探伤源（历史）"]},104:{u:"第一个超锕系元素。科学家逐个原子地研究它的化学性质，用以检验相对论效应是否会打乱周期律。",a:[]},105:{u:"半衰期仅数十秒。化学实验必须在合成后的几秒内完成，是「单原子化学」的极限挑战。",a:[]},106:{u:"以西博格命名，是首个以在世科学家命名的元素，当时曾引发不小的争议。",a:[]},107:{u:"命名自玻尔。实验证实它的化学性质与同族的铼相似，支持了周期表在超重区依然有效。",a:[]},108:{u:"已知密度最大的元素（推算约 41 g/cm³）。曾成功合成四氧化物，证明它确实像同族的锇。",a:[]},109:{u:"命名自发现核裂变理论解释的迈特纳。至今合成总量不足百个原子。",a:[]},110:{u:"命名自德国达姆施塔特的重离子研究所 —— 107 到 112 号元素都在那里首次合成。",a:[]},111:{u:"命名自 X 射线的发现者伦琴，恰好在其发现 X 射线一百周年前后被确认。",a:[]},112:{u:"命名自哥白尼。理论预测它可能像汞一样具有挥发性，实验结果也支持这一点。",a:[]},113:{u:"第一个由亚洲团队（日本理化学研究所）发现并命名的元素，名字取自日本的古称。",a:[]},114:{u:"命名自弗廖罗夫。它被认为接近理论预测的「稳定岛」—— 超重元素半衰期可能重新变长的区域。",a:[]},115:{u:"命名自莫斯科州。合成它需要用钙 48 离子束轰击镅靶，持续数月才能得到几个原子。",a:[]},116:{u:"命名自劳伦斯利弗莫尔国家实验室。半衰期仅数十毫秒，几乎在生成的瞬间就衰变。",a:[]},117:{u:"目前唯一需要专门在反应堆中培育锫靶材才能合成的元素，整个流程耗时两年以上。",a:[]},118:{u:"已知最重的元素，位于周期表最后一格。虽在稀有气体列，理论却预测它可能并不惰性，甚至可能是固体。",a:[]},57:{u:"镍氢电池的负极合金以镧为主，混合动力车电池长期依赖它；高折射率镧玻璃则用于相机镜头。",a:["镍氢电池负极合金","相机与望远镜镜头玻璃","石油催化裂化","打火石合金"]},58:{u:"储量最丰富的稀土。二氧化铈是玻璃抛光的行业标准，手机屏幕和镜片抛光几乎都用它。",a:["玻璃与屏幕抛光粉","汽车尾气催化储氧","自清洁烤箱涂层","打火石与防紫外玻璃"]},59:{u:"掺镨的玻璃能滤掉钠光的强黄光，是焊工和玻璃工护目镜的标准材料；也用于强永磁体。",a:["焊工与玻璃工护目镜","钕镨永磁体","玻璃与陶瓷黄绿着色","光纤放大器"]},60:{u:"钕铁硼是目前最强的永磁体，让耳机、硬盘、电动车电机和风力发电机得以做小做强 —— 现代生活到处是它。",a:["耳机与扬声器磁体","电动车驱动电机","风力发电机","硬盘音圈与磁力扣"]},61:{u:"唯一没有稳定同位素的轻稀土，自然界几乎不存在。曾用于夜光表盘，现主要作核电池和厚度计。",a:["核电池（航天与心脏起搏器研究）","厚度测量仪","夜光涂料（历史用途）"]},62:{u:"钐钴磁体在 300 ℃ 以上仍不退磁，用于航空航天和军用电机等钕磁体扛不住的高温场合。",a:["耐高温钐钴磁体","骨癌骨转移止痛放射药","核反应堆中子吸收","航空电机与传感器"]},63:{u:"发光效率极高的红色与蓝色荧光粉基础，彩色显示和节能灯的色彩靠它；欧元纸币的防伪荧光也含铕。",a:["显示器与节能灯红蓝荧光粉","欧元纸币防伪","LED 照明显色","核反应堆控制"]},64:{u:"钆的顺磁性极强，注射钆造影剂能让 MRI 中的血管和病灶大幅提高对比度，是临床最常用的 MRI 造影剂。",a:["MRI 造影剂","中子屏蔽与反应堆控制","磁制冷技术","绿色荧光粉与 X 光增感屏"]},65:{u:"三基色荧光灯里的绿色成分主要来自铽；铽合金还有极强的磁致伸缩效应，用于声呐和精密驱动器。",a:["荧光灯与显示器绿色荧光粉","声呐磁致伸缩换能器","磁光存储介质","固态照明"]},66:{u:"给钕磁体加镝能显著提高耐热性，电动车电机和风机在高温下不退磁全靠它 —— 也是最紧缺的稀土之一。",a:["电动车与风机磁体耐热添加","核反应堆控制棒","磁致伸缩材料","高强度激光材料"]},67:{u:"钬激光能在水中高效切割软组织，是碎肾结石和前列腺微创手术的主流器械。",a:["钬激光碎石与前列腺手术","磁体磁极片（磁矩最强）","玻璃与立方氧化锆着色","核反应堆控制"]},68:{u:"掺铒光纤放大器让光信号无需转成电信号就能直接放大，是跨洋海底光缆和整个互联网骨干的基础。",a:["光纤放大器（互联网骨干）","铒激光皮肤与牙科治疗","粉红色玻璃与釉","核燃料控制"]},69:{u:"最稀有的稳定稀土之一。铥同位素做成便携式 X 射线源，无需电源即可在野外和战地拍片。",a:["便携式 X 射线源","铥激光外科手术","高温超导材料","激光测距"]},70:{u:"掺镱光纤激光器电光转换效率极高，已成为工业金属切割和焊接的主力设备；也用于最精确的原子钟。",a:["光纤激光切割与焊接","光晶格原子钟","地震与地质应变计","不锈钢晶粒细化"]},71:{u:"硅酸镥晶体探测伽马射线又快又灵敏，是 PET 扫描仪的核心探测材料；镥 177 则用于靶向放疗。",a:["PET 扫描探测晶体","前列腺癌靶向放疗","石油裂化催化剂","发光二极管材料"]},89:{u:"锕 225 释放的 α 粒子射程极短，能在杀死癌细胞的同时几乎不伤及周围组织，是靶向放疗的前沿药物。",a:["靶向 α 放疗（前列腺癌等）","中子源"]},90:{u:"储量约为铀的三到四倍，且难以用于武器，钍基熔盐堆因此被视为下一代核能的重要路线之一。",a:["钍基核燃料研究","高折射率光学玻璃","气灯纱罩（历史）","高温合金与焊条"]},91:{u:"天然存在量极微且提取困难，价格昂贵。除同位素年代测定外没有实际应用。",a:["海洋沉积物年代测定"]},92:{u:"核电站的燃料，全球约十分之一的电力由铀裂变提供；贫铀密度极大，用于装甲和穿甲弹。",a:["核电站燃料","核武器","贫铀装甲与配重","铀玻璃（历史）"]},93:{u:"第一个超铀元素。主要作为生产钚 238 的原料，也用于探测高能中子的仪器。",a:["钚 238 生产原料","高能中子探测器"]},94:{u:"钚 238 的衰变热能稳定供电数十年，旅行者号、好奇号和毅力号等深空探测器都靠它工作。",a:["深空探测器同位素电池","核武器","心脏起搏器电源（历史）"]},95:{u:"离日常生活最近的锕系元素 —— 绝大多数离子式烟雾报警器里都有极微量的镅 241，靠它电离空气探测烟雾。",a:["离子式烟雾报警器","厚度与密度测量仪","中子源与石油测井"]},96:{u:"火星车上的 α 粒子 X 射线谱仪用锔 244 轰击岩石以测定成分 —— 勇气号、机遇号和好奇号都带着它。",a:["火星车岩石成分分析仪","同位素电源研究"]},97:{u:"只能在反应堆中以微克级合成。唯一实际用途是作为合成更重元素（如 117 号）的靶材。",a:["合成超重元素的靶材"]},98:{u:"极强的中子源，一微克每秒放出数百万个中子。用于金矿银矿勘探、反应堆启动和部分肿瘤的近距离治疗。",a:["便携中子源（探矿与测井）","反应堆启动中子源","中子俘获癌症治疗"]},99:{u:"在首次氢弹试验的残骸中被发现。产量以微克计，除基础研究外没有应用。",a:[]},100:{u:"目前只能通过中子俘获少量制得，且无法以称量级获得。仅用于核物理研究。",a:[]},101:{u:"为纪念门捷列夫命名。每次只能合成几个原子，仅用于验证锕系元素的化学行为。",a:[]},102:{u:"命名自诺贝尔。半衰期以分钟计，只能以单个原子的规模研究，没有任何实际用途。",a:[]},103:{u:"锕系的最后一个元素。它的电子排布曾长期存疑，2015 年的实验最终确认了周期表的排布方式。",a:[]}};
