  const oldRow=DB.PT.find(p=>p[0]===e[1]);
  const valTxt=oldRow?(oldRow[5]==='—'?(PTS.lang==='en'?'No stable valence':'极不稳定，未确立常见价态'):oldRow[5]):'—';
  let h='<button class="cls" id="ptClose">✕</button>';
  h+='<aside class="pt-info">';
