/* 画布点击拾取（区分拖拽：位移 >5px 视为旋转） */
(function(){
  const cv=document.getElementById('cv');
  let down=null;
  cv.addEventListener('pointerdown',e=>{down=[e.clientX,e.clientY];});
  cv.addEventListener('click',e=>{
    if(!UI.sel||UI.sel.kind!=='pt')return;
    if(down&&Math.hypot(e.clientX-down[0],e.clientY-down[1])>5)return;
    const r=cv.getBoundingClientRect();
    const dpr=cv.width/r.width||1;
    const sx=(e.clientX-r.left)*dpr,sy=(e.clientY-r.top)*dpr;
    let best=-1,bd=1e9;
    DB.PT.forEach((el,i)=>{
      const x=(el[2]-9.5),z=(el[3]-5.5);
      const h=0.42+el[6]*0.26;
      const p=E3.proj(x,h,z);
      if(p[2]<0.3)return;
      const d=Math.hypot(p[0]-sx,p[1]-sy);
      if(d<bd){bd=d;best=i;}
    });
    const cellR=0.7*E3.cam.fov/E3.cam.dist; /* 块投影半径的近似 */
    if(best>=0&&bd<cellR*1.6)openPTDetail(best+1);
  });
})();
/* ---------- 实验报告生成器（灵感⑥：现象记录 + 安全要点 + 3D 定格导出） ---------- */
function openReport(item){
  /* 先展示加载态，等两帧渲染完成后再截取 3D 定格图（避免拿到导航切换前的旧帧） */
  const d=$('rptDialog');
  d.innerHTML='<div class="quiz-head"><h3>实验报告 · '+item.name+'</h3><button class="btn-sub" id="rClose" aria-label="关闭报告">关闭</button></div><div class="rpt-body" style="text-align:center;padding:48px 20px;color:#7a938d">正在生成报告与装置定格图…</div>';
  $('rptMask').classList.add('show');
  const rc0=$('rClose');if(rc0)rc0.addEventListener('click',()=>$('rptMask').classList.remove('show'));
  requestAnimationFrame(()=>requestAnimationFrame(()=>{
    let shot=null;
    try{ shot=window.ChemSpatial?.capture()||document.getElementById('cv').toDataURL('image/png'); }catch(e){}
    buildReport(item,shot);
  }));
}
function buildReport(item,shot){
  if(window.ChemReports){window.ChemReports.open(item,shot);return;}
  const d=$('rptDialog');
  const today=new Date();
  const ds=today.getFullYear()+'-'+String(today.getMonth()+1).padStart(2,'0')+'-'+String(today.getDate()).padStart(2,'0');
  let h='<div class="quiz-head"><h3>实验报告 · '+item.name+'</h3><button class="btn-sub" id="rClose" aria-label="关闭报告">关闭</button></div>';
  h+='<div class="rpt-body">';
  h+='<table><tr><th style="width:22%">实验名称</th><td>'+item.name+'</td><th style="width:18%">日期</th><td style="width:24%">'+ds+'</td></tr>';
  h+='<tr><th>班级 / 姓名</th><td><span class="rpt-fill">（打印后填写）</span></td><th>指导教师</th><td><span class="rpt-fill">（打印后填写）</span></td></tr></table>';
  h+='<h4>一、实验原理</h4><p>'+item.principle+'</p>';
  h+='<h4>二、仪器与试剂</h4><p>仪器：'+item.apparatus.join('、')+'<br>试剂：'+item.reagents.join('、')+'</p>';
  h+='<h4>三、实验步骤与现象记录</h4>';
  h+='<table><tr><th style="width:20%">步骤</th><th style="width:44%">操作要点</th><th>现象记录（课堂填写）</th></tr>';
  item.steps.forEach(s=>{ h+='<tr><td>'+s.t+'</td><td>'+s.txt+'</td><td class="rpt-fill">　</td></tr>'; });
  h+='</table>';
  h+='<h4>四、现象要点（参考）</h4><ul>'+item.phenomena.map(p=>'<li>'+p+'</li>').join('')+'</ul>';
  if(shot)h+='<h4>五、装置示意图（3D 定格导出）</h4><img src="'+shot+'" alt="实验装置 3D 定格图">';
  h+='<h4>六、安全要点</h4><ul>'+item.safety.map(s=>'<li>'+s+'</li>').join('')+'</ul>';
  h+='<h4>七、结论与反思（课堂填写）</h4><p class="rpt-fill">　</p>';
  h+='</div>';
  h+='<div class="q-foot"><button class="btn-main" id="rDl">下载报告（HTML）</button><button class="btn-sub" id="rPrint">打印 / 存为 PDF</button><button class="btn-sub" id="rClose2">关闭</button></div>';
  d.innerHTML=h;
  $('rptMask').classList.add('show');
  d.scrollTop=0;
  const dl=$('rDl');
  if(dl)dl.addEventListener('click',()=>downloadReport(item,shot,ds));
  const pr=$('rPrint');
  if(pr)pr.addEventListener('click',()=>{
    const w=open('','_blank');
    if(!w){toast('浏览器拦截了新窗口，请允许弹窗后重试');return;}
    w.document.write(reportHTML(item,shot,ds));
    w.document.close();
    setTimeout(()=>{try{w.print();}catch(e){}},400);
  });
  const rc=$('rClose');if(rc)rc.addEventListener('click',()=>$('rptMask').classList.remove('show'));
  const rc2=$('rClose2');if(rc2)rc2.addEventListener('click',()=>$('rptMask').classList.remove('show'));
}
function reportHTML(item,shot,ds){
  let rows='';
  item.steps.forEach(s=>{rows+='<tr><td>'+s.t+'</td><td>'+s.txt+'</td><td>　</td></tr>';});
  return '<!DOCTYPE html><html lang="zh-CN"><head><meta charset="UTF-8"><title>实验报告 · '+item.name+'</title><style>'+
  'body{font-family:"PingFang SC","Microsoft YaHei",sans-serif;max-width:860px;margin:24px auto;padding:0 20px;color:#1a3a36;line-height:1.8}'+
  'h1{font-size:22px;border-bottom:3px solid #0e6b57;padding-bottom:8px;color:#0e6b57}'+
  'h3{font-size:15px;color:#0e6b57;margin:20px 0 8px}'+
  'table{width:100%;border-collapse:collapse;margin:8px 0}th,td{border:1px solid #b9d8d0;padding:7px 10px;font-size:13px;text-align:left;vertical-align:top}'+
  'th{background:#eafaf5;color:#0e6b57}img{max-width:100%;border:1px solid #b9d8d0;border-radius:6px}'+
  'ul{padding-left:22px}li{font-size:13px;margin-bottom:3px}p{font-size:13px}.fill{color:#8aa8a2;font-style:italic}'+
  '</style></head><body><h1>实验报告 · '+item.name+'</h1>'+
  '<table><tr><th>实验名称</th><td>'+item.name+'</td><th>日期</th><td>'+ds+'</td></tr><tr><th>班级 / 姓名</th><td class="fill">（填写）</td><th>指导教师</th><td class="fill">（填写）</td></tr></table>'+
  '<h3>一、实验原理</h3><p>'+item.principle+'</p>'+
  '<h3>二、仪器与试剂</h3><p>仪器：'+item.apparatus.join('、')+'<br>试剂：'+item.reagents.join('、')+'</p>'+
  '<h3>三、实验步骤与现象记录</h3><table><tr><th style="width:18%">步骤</th><th style="width:46%">操作要点</th><th>现象记录</th></tr>'+rows+'</table>'+
  '<h3>四、现象要点（参考）</h3><ul>'+item.phenomena.map(p=>'<li>'+p+'</li>').join('')+'</ul>'+
  (shot?'<h3>五、装置示意图（3D 定格导出）</h3><img src="'+shot+'" alt="装置示意图">':'')+
  '<h3>六、安全要点</h3><ul>'+item.safety.map(s=>'<li>'+s+'</li>').join('')+'</ul>'+
  '<h3>七、结论与反思</h3><p class="fill">　</p>'+
  '<p style="text-align:right;color:#8aa8a2;font-size:11px">3D 化学实验工作室 · 本地生成</p></body></html>';
}
function downloadReport(item,shot,ds){
  const blob=new Blob([reportHTML(item,shot,ds)],{type:'text/html;charset=utf-8'});
  const a=document.createElement('a');
  a.href=URL.createObjectURL(blob);
  a.download='实验报告-'+item.name+'-'+ds+'.html';
  document.body.appendChild(a);a.click();
  setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},600);
  toast('报告已下载：实验报告-'+item.name+'-'+ds+'.html');
}
