let visited=store.get('visited',{});
function addRecent(kind,id){
  recent=recent.filter(r=>!(r.k===kind&&r.i===id));
  recent.unshift({k:kind,i:id,t:Date.now()});
  recent=recent.slice(0,12);
  store.set('recent',recent);
  visited[kind+':'+id]=1;
  store.set('visited',visited);
}
