  h+='<div class="stat"><div class="v">'+DB.app.length+'</div><div class="l">化学仪器</div></div>';
  h+='<div class="stat"><div class="v">'+DB.mols.length+'</div><div class="l">分子与晶体模型</div></div>';
  h+='<div class="stat"><div class="v">'+DB.exps.length+'</div><div class="l">化学实验</div></div>';
  h+='<div class="stat"><div class="v">118</div><div class="l">周期表元素</div></div>';
  h+='</div>';
  /* ---------- 学习进度卡（灵感⑦：预习—观察—自测 学习环） ---------- */
