/* ---------- 搜索 ---------- */
function searchAll(kw){
  const res=[];
  ['sub','app','mol','exp'].forEach(kind=>{
    DATA[kind].forEach(it=>{
      const hay=(it.name+' '+(it.formula||'').replace(/<[^>]+>/g,'')+' '+(it.tags||[]).join(' ')+' '+it.subName).toLowerCase();
      if(hay.indexOf(kw)>=0)res.push({kind:kind,it:it});
    });
  });
  return res.slice(0,14);
}
const sIn=$('searchInput'),sDrop=$('searchDrop');
sIn.addEventListener('input',()=>{
  const kw=sIn.value.trim().toLowerCase();
  if(!kw){sDrop.classList.remove('show');return;}
  const res=searchAll(kw);
  if(!res.length){sDrop.innerHTML='<div class="sd-item" style="color:var(--text2)">未找到匹配项</div>';sDrop.classList.add('show');return;}
  let h='',lastKind='';
  res.forEach(r=>{
    if(r.kind!==lastKind){lastKind=r.kind;const nm={sub:'化学物品',app:'化学仪器',mol:'分子与晶体模型',exp:'化学实验'}[r.kind];h+='<div class="sd-group">'+nm+'</div>';}
    h+='<div class="sd-item" data-kind="'+r.kind+'" data-id="'+r.it.id+'"><b>'+r.it.name+'</b><span class="fm">'+(r.it.formula||'').replace(/<[^>]+>/g,'')+'</span></div>';
  });
  sDrop.innerHTML=h;sDrop.classList.add('show');
  sDrop.querySelectorAll('.sd-item[data-id]').forEach(b=>{
    b.addEventListener('click',()=>{
      sDrop.classList.remove('show');sIn.value='';
      select(b.getAttribute('data-kind'),b.getAttribute('data-id'));
    });
  });
});
document.addEventListener('click',e=>{
  if(!e.target.closest('.searchbox'))sDrop.classList.remove('show');
});
sIn.addEventListener('keydown',e=>{
  if(e.key==='Enter'){
    const kw=sIn.value.trim().toLowerCase();
    if(kw){const res=searchAll(kw);if(res.length){select(res[0].kind,res[0].it.id);sDrop.classList.remove('show');sIn.value='';}}
  }
});
